126	    public void onEventMainThread(QueueEvent event) {
127	        Log.d(TAG, "onEventMainThread() called with: " + "event = [" + event + "]");
128	        if(queue == null || recyclerAdapter == null) {
129	            return;
130	        }
131	        switch(event.action) {
132	            case ADDED:
133	                queue.add(event.position, event.item);
134	                recyclerAdapter.notifyItemInserted(event.position);
135	                break;
136	            case SET_QUEUE:
137	                queue = event.items;
138	                recyclerAdapter.notifyDataSetChanged();
139	                break;
140	            case REMOVED:
141	            case IRREVERSIBLE_REMOVED:
142	                int position = FeedItemUtil.indexOfItemWithId(queue, event.item.getId());
143	                queue.remove(position);
144	                recyclerAdapter.notifyItemRemoved(position);
145	                break;
146	            case CLEARED:
147	                queue.clear();
148	                recyclerAdapter.notifyDataSetChanged();
149	                break;
150	            case SORTED:
151	                queue = event.items;
152	                recyclerAdapter.notifyDataSetChanged();
153	                break;
154	            case MOVED:
155	                return;
156	        }
157	        saveScrollPosition();
158	        onFragmentLoaded(false);
159	    }
160	
161	    public void onEventMainThread(FeedItemEvent event) {
162	        Log.d(TAG, "onEventMainThread() called with: " + "event = [" + event + "]");
163	        if(queue == null || recyclerAdapter == null) {
164	            return;
165	        }
166	        for(int i=0, size = event.items.size(); i < size; i++) {
167	            FeedItem item = event.items.get(i);
168	            int pos = FeedItemUtil.indexOfItemWithId(queue, item.getId());
169	            if(pos >= 0) {
170	                queue.remove(pos);
171	                queue.add(pos, item);
172	                recyclerAdapter.notifyItemChanged(pos);
173	            }
174	        }
175	    }
