177	    public void onEventMainThread(DownloadEvent event) {
178	        Log.d(TAG, "onEventMainThread() called with: " + "event = [" + event + "]");
179	        DownloaderUpdate update = event.update;
180	        downloaderList = update.downloaders;
181	        if (isUpdatingFeeds != update.feedIds.length > 0) {
182	            getActivity().supportInvalidateOptionsMenu();
183	        }
184	        if (recyclerAdapter != null && update.mediaIds.length > 0) {
185	            for (long mediaId : update.mediaIds) {
186	                int pos = FeedItemUtil.indexOfItemWithMediaId(queue, mediaId);
187	                if (pos >= 0) {
188	                    recyclerAdapter.notifyItemChanged(pos);
189	                }
190	            }
191	        }
192	    }
