348	        Log.d(TAG, "onContextItemSelected() called with: " + "item = [" + item + "]");
349	        if(!isVisible()) {
350	            return false;
351	        }
352	        FeedItem selectedItem = recyclerAdapter.getSelectedItem();
353	        if (selectedItem == null) {
354	            Log.i(TAG, "Selected item was null, ignoring selection");
355	            return super.onContextItemSelected(item);
356	        }
357	
358	        switch(item.getItemId()) {
359	            case R.id.move_to_top_item:
360	                int position = FeedItemUtil.indexOfItemWithId(queue, selectedItem.getId());
361	                queue.add(0, queue.remove(position));
362	                recyclerAdapter.notifyItemMoved(position, 0);
363	                DBWriter.moveQueueItemToTop(selectedItem.getId(), true);
364	                return true;
365	            case R.id.move_to_bottom_item:
366	                position = FeedItemUtil.indexOfItemWithId(queue, selectedItem.getId());
367	                queue.add(queue.size()-1, queue.remove(position));
368	                recyclerAdapter.notifyItemMoved(position, queue.size()-1);
369	                DBWriter.moveQueueItemToBottom(selectedItem.getId(), true);
370	                return true;
371	            default:
372	                return FeedItemMenuHandler.onMenuItemClicked(getActivity(), item.getItemId(), selectedItem);
373	        }
374	    }
