397	
398	                // Position tracking whilst dragging
399	                int dragFrom = -1;
400	                int dragTo = -1;
401	
402	                @Override
403	                public boolean onMove(RecyclerView recyclerView, RecyclerView.ViewHolder viewHolder, RecyclerView.ViewHolder target) {
404	                    int fromPosition = viewHolder.getAdapterPosition();
405	                    int toPosition = target.getAdapterPosition();
406	
407	                    // Update tracked position
408	                    if(dragFrom == -1) {
409	                        dragFrom =  fromPosition;
410	                    }
411	                    dragTo = toPosition;
412	
413	                    int from = viewHolder.getAdapterPosition();
414	                    int to = target.getAdapterPosition();
415	                    Log.d(TAG, "move(" + from + ", " + to + ") in memory");
416	                    if(from >= queue.size() || to >= queue.size()) {
417	                        return false;
418	                    }
419	                    queue.add(to, queue.remove(from));
420	                    recyclerAdapter.notifyItemMoved(from, to);
421	                    return true;
422	                }
423	
424	                @Override
425	                public void onSwiped(RecyclerView.ViewHolder viewHolder, int direction) {
426	                    if(subscription != null) {
427	                        subscription.unsubscribe();
428	                    }
429	                    final int position = viewHolder.getAdapterPosition();
430	                    Log.d(TAG, "remove(" + position + ")");
431	                    final FeedItem item = queue.get(position);
432	                    final boolean isRead = item.isPlayed();
433	                    DBWriter.markItemPlayed(FeedItem.PLAYED, false, item.getId());
434	                    DBWriter.removeQueueItem(getActivity(), item, true);
435	                    Snackbar snackbar = Snackbar.make(root, getString(R.string.marked_as_read_label), Snackbar.LENGTH_LONG);
436	                    snackbar.setAction(getString(R.string.undo), v -> {
437	                        DBWriter.addQueueItemAt(getActivity(), item.getId(), position, false);
438	                        if(!isRead) {
439	                            DBWriter.markItemPlayed(FeedItem.UNPLAYED, item.getId());
440	                        }
441	                    });
442	                    snackbar.show();
443	                }
