470	                public void clearView(RecyclerView recyclerView,
471	                                      RecyclerView.ViewHolder viewHolder) {
472	                    super.clearView(recyclerView, viewHolder);
473	
474	                    // Check if drag finished
475	                    if(dragFrom != -1 && dragTo != -1 && dragFrom != dragTo) {
476	                        reallyMoved(dragFrom, dragTo);
477	                    }
478	
479	                    dragFrom = dragTo = -1;
480	
481	                    if (viewHolder instanceof QueueRecyclerAdapter.ItemTouchHelperViewHolder) {
482	                        QueueRecyclerAdapter.ItemTouchHelperViewHolder itemViewHolder =
483	                                (QueueRecyclerAdapter.ItemTouchHelperViewHolder) viewHolder;
484	                        itemViewHolder.onItemClear();
