587	                    }
588	                }
589	            }
590	            return 0;
591	        }
592	        @Override
593	        public int getItemDownloadProgressPercent(FeedItem item) {
594	            if (downloaderList != null) {
595	                for (Downloader downloader : downloaderList) {
596	                    if (downloader.getDownloadRequest().getFeedfileType() == FeedMedia.FEEDFILETYPE_FEEDMEDIA
597	                            && downloader.getDownloadRequest().getFeedfileId() == item.getMedia().getId()) {
598	                        return downloader.getDownloadRequest().getProgressPercent();
599	                    }
600	                }
601	            }
602	            return 0;
603	        }
604	
605	        @Override
606	        public LongList getQueueIds() {
607	            return queue != null ? LongList.of(FeedItemUtil.getIds(queue)) : new LongList(0);
608	        }
609	    };
610	
611	    private final EventDistributor.EventListener contentUpdate = new EventDistributor.EventListener() {
612	        @Override
613	        public void update(EventDistributor eventDistributor, Integer arg) {
614	            if ((arg & EVENTS) != 0) {
615	                Log.d(TAG, "arg: " + arg);
616	                loadItems(false);
617	                if (isUpdatingFeeds != updateRefreshMenuItemChecker.isRefreshing()) {
618	                    getActivity().supportInvalidateOptionsMenu();
619	                }
620	            }
621	        }
622	    };
623	
624	    private void loadItems(final boolean restoreScrollPosition) {
625	        Log.d(TAG, "loadItems()");
626	        if(subscription != null) {
627	            subscription.unsubscribe();
628	        }
629	        if (queue == null) {
630	            recyclerView.setVisibility(View.GONE);
631	            txtvEmpty.setVisibility(View.GONE);
632	            progLoading.setVisibility(View.VISIBLE);
633	        }
634	        subscription = Observable.fromCallable(DBReader::getQueue)
635	                .subscribeOn(Schedulers.newThread())
636	                .observeOn(AndroidSchedulers.mainThread())
637	                .subscribe(items -> {
638	                    if(items != null) {
639	                        progLoading.setVisibility(View.GONE);
640	                        queue = items;
641	                        onFragmentLoaded(restoreScrollPosition);
642	                        if(recyclerAdapter != null) {
643	                            recyclerAdapter.notifyDataSetChanged();
644	                        }
645	                    }
646	                }, error -> Log.e(TAG, Log.getStackTraceString(error)));
647	    }
648	
649	}
