419	    public void onEventMainThread(FeedItemEvent event) {
420	        Log.d(TAG, "onEventMainThread() called with: " + "event = [" + event + "]");
421	        if(episodes == null || listAdapter == null) {
422	            return;
423	        }
424	        for(int i=0, size = event.items.size(); i < size; i++) {
425	            FeedItem item = event.items.get(i);
426	            int pos = FeedItemUtil.indexOfItemWithId(episodes, item.getId());
427	            if(pos >= 0) {
428	                episodes.remove(pos);
429	                episodes.add(pos, item);
430	                listAdapter.notifyItemChanged(pos);
431	            }
432	        }
433	    }
