468	    void loadItems() {
469	        if(subscription != null) {
470	            subscription.unsubscribe();
471	        }
472	        if (viewsCreated && !itemsLoaded) {
473	            recyclerView.setVisibility(View.GONE);
474	            progLoading.setVisibility(View.VISIBLE);
475	        }
476	        subscription = Observable.fromCallable(this::loadData)
477	                .subscribeOn(Schedulers.newThread())
478	                .observeOn(AndroidSchedulers.mainThread())
479	                .subscribe(data -> {
480	                    recyclerView.setVisibility(View.VISIBLE);
481	                    progLoading.setVisibility(View.GONE);
482	                    if (data != null) {
483	                        episodes = data;
484	                        itemsLoaded = true;
485	                        if (viewsCreated) {
486	                            onFragmentLoaded();
487	                        }
488	                    }
489	                }, error -> Log.e(TAG, Log.getStackTraceString(error)));
490	    }
